mapper.select:
SELECT ROW_NUMBER() OVER (ORDER BY QNA_ID DESC) AS RNUM, QNA_ID AS QNA_NO, MEMBER_ID AS MEMBER_ID, QNA_NAME AS QNA_NAME, TITLE AS QNA_TITLE, /* 기존 JSP 화면 일치형 */ CONTENT AS QNA_CONTENT, /* 기존 JSP 화면 일치형 */ TO_CHAR(CREATED_AT, 'YYYY.MM.DD HH24:MI:SS') AS QNA_DATE,
/* 💡 실제 추가된 답변 컬럼(QNA_AN)은 정상 조회하도록 세팅 */ QNA_AN AS QNA_AN,
/* 테이블에 없는 나머지 명세서용 컬럼은 가상 컬럼으로 안전 방어 */ '' AS QNA_CATEGORY, '0' AS IS_SECRET, '0' AS QNA_DELETE FROM QNA_POSTS WHERE QNA_ID = #{QNA_ID}

mapper.update:
UPDATE QNA_POSTS
   SET QNA_AN = #{ANSWER, jdbcType=VARCHAR} /* 관리자가 입력한 답변 매핑 */
 WHERE QNA_ID = #{QNA_ID, jdbcType=NUMERIC}
